import React, { useState, useEffect, useRef } from 'react';
import { Card, Button, Alert, api } from '../App';

export default function MarkingPage() {
  const [allParties, setAllParties] = useState([]);
  const [saleNos,    setSaleNos]    = useState([]);
  const [selParties, setSelParties] = useState([]);
  const [saleNo,     setSaleNo]     = useState('');
  const [partySearch,setPartySearch]= useState('');

  const [preview,      setPreview]      = useState([]);
  const [partyOrder,   setPartyOrder]   = useState([]);
  const [prices,       setPrices]       = useState({});
  const [skipRows,     setSkipRows]     = useState({});
  const [extraParties, setExtraParties] = useState({});
  const [addInputs,    setAddInputs]    = useState({});
  const [dupWarnings,  setDupWarnings]  = useState([]);

  const [loading, setLoading] = useState(false);
  const [saving,  setSaving]  = useState(false);
  const [alert,   setAlert]   = useState(null);
  const addInputRefs = useRef({});

  useEffect(() => {
    Promise.all([
      api.get('/parties').catch(() => ({ data: [] })),
      api.get('/import/sale-numbers').catch(() => ({ data: [] }))
    ]).then(([p, s]) => { setAllParties(p.data); setSaleNos(s.data); });
  }, []);

  // ── Helpers (defined ONCE, before return) ─────────────────────────────────
  const getCodeSuggestions = (val) => {
    if (!val || val.length < 1) return [];
    return allParties.filter(p => p.party_code.startsWith(val.toUpperCase())).slice(0, 6);
  };

  const toggleParty = (p) => {
    setSelParties(prev =>
      prev.find(x => x.id === p.id)
        ? prev.filter(x => x.id !== p.id)
        : [...prev, { id: p.id, party_name: p.party_name, party_code: p.party_code }]
    );
  };

  const filteredParties = allParties.filter(p =>
    p.party_name.toLowerCase().includes(partySearch.toLowerCase()) ||
    p.party_code.toLowerCase().includes(partySearch.toLowerCase())
  );

  const selectAll   = () => setSelParties(filteredParties.map(p => ({ id: p.id, party_name: p.party_name, party_code: p.party_code })));
  const deselectAll = () => setSelParties([]);

  const runPreview = async () => {
    if (!selParties.length || !saleNo) {
      setAlert({ msg: 'Select at least one party and sale number', type: 'error' });
      return;
    }
    setLoading(true); setAlert(null); setDupWarnings([]);
    try {
      const r = await api.post('/marking/preview', {
        party_ids: selParties.map(p => p.id),
        sale_no: saleNo
      });
      setPreview(r.data.lots || []);
      setPartyOrder(r.data.parties || []);
      const init = {};
      (r.data.lots || []).forEach(row => { init[row.catalogue_id] = row.suggested_price || ''; });
      setPrices(init); setSkipRows({}); setExtraParties({}); setAddInputs({});
      if (!r.data.lots?.length)
        setAlert({ msg: 'No lots found. Check Party Master garden mappings and grade sample settings.', type: 'warning' });
    } catch (e) {
      setAlert({ msg: e.response?.data?.error || e.message, type: 'error' });
    } finally { setLoading(false); }
  };

  const addExtraParty = (catalogueId) => {
    const code = (addInputs[catalogueId] || '').trim().toUpperCase();
    if (!code) return;
    const p = allParties.find(x => x.party_code === code);
    if (!p) { setDupWarnings([`Party code "${code}" not found`]); return; }

    const alreadyMain  = partyOrder.find(x => x.party_code === code);
    const alreadyExtra = extraParties[catalogueId] &&
      Object.values(extraParties[catalogueId]).find(x => x.party_code === code);
    const lot = preview.find(x => x.catalogue_id === catalogueId);

    if (alreadyMain) {
      setDupWarnings([`⚠️ ${p.party_name} (${code}) is already in the main party list for ${lot?.garden}/${lot?.grade}`]);
      return;
    }
    if (alreadyExtra) {
      setDupWarnings([`⚠️ ${p.party_name} (${code}) already added for ${lot?.garden}/${lot?.grade}`]);
      return;
    }

    setDupWarnings([]);
    setExtraParties(prev => {
      const curr = prev[catalogueId] || {};
      const nextIdx = partyOrder.length + Object.keys(curr).length + 1;
      return {
        ...prev,
        [catalogueId]: {
          ...curr,
          [`P${nextIdx}`]: { party_id: p.id, party_name: p.party_name, party_code: code }
        }
      };
    });
    setAddInputs(prev => ({ ...prev, [catalogueId]: '' }));
  };

  const handleAddKeyDown = (e, catalogueId) => {
    if (e.key === 'Enter') { e.preventDefault(); addExtraParty(catalogueId); }
  };

  const save = async () => {
    const markings = preview.filter(r => !skipRows[r.catalogue_id]).map(row => ({
      ...row,
      party_cols:    row.party_cols,
      extra_parties: extraParties[row.catalogue_id] || {},
      final_price:   prices[row.catalogue_id] || row.suggested_price,
      skip:          false
    }));
    if (!markings.length) { setAlert({ msg: 'No markings to save', type: 'warning' }); return; }
    setSaving(true);
    try {
      const r = await api.post('/marking/save', { markings, sale_no: saleNo, party_order: partyOrder });
      setAlert({
        msg: `✅ ${r.data.saved} markings saved.${r.data.duplicates ? ` ${r.data.duplicates} duplicates skipped.` : ''}`,
        type: 'success'
      });
      if (r.data.warnings?.length) setDupWarnings(r.data.warnings);
      setPreview([]);
    } catch (e) {
      setAlert({ msg: e.response?.data?.error || e.message, type: 'error' });
    } finally { setSaving(false); }
  };

  const activeCount = preview.filter(r => !skipRows[r.catalogue_id]).length;

  // ── Render ────────────────────────────────────────────────────────────────
  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>✅ Create Markings</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 16 }}>
        Select parties and sale. Lots are fetched based on each party's mapping settings.
      </p>

      {alert && <Alert msg={alert.msg} type={alert.type} />}

      {dupWarnings.length > 0 && (
        <div style={{ background: '#fffbeb', border: '1px solid #fde68a', borderRadius: 8, padding: '8px 14px', marginBottom: 12, fontSize: 12, color: '#92400e' }}>
          {dupWarnings.map((w, i) => <div key={i}>{w}</div>)}
        </div>
      )}

      <div style={{ display: 'grid', gridTemplateColumns: '340px 1fr', gap: 16, marginBottom: 16 }}>

        {/* ── LEFT: Full party list ── */}
        <Card style={{ padding: 16 }}>
          <div style={{ fontWeight: 700, fontSize: 14, color: '#1a3c5e', marginBottom: 10 }}>Select Parties</div>
          <input
            value={partySearch} onChange={e => setPartySearch(e.target.value)}
            placeholder="Search party name or code…"
            style={{ width: '100%', padding: '7px 10px', border: '1.5px solid #e2e8f0', borderRadius: 6, fontSize: 13, marginBottom: 8 }}
          />
          <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
            <Button size="sm" variant="outline" onClick={selectAll}   style={{ flex: 1, fontSize: 11 }}>✓ Select All</Button>
            <Button size="sm" variant="outline" onClick={deselectAll} style={{ flex: 1, fontSize: 11 }}>✕ Deselect All</Button>
          </div>

          <div style={{ maxHeight: 480, overflowY: 'auto', border: '1px solid #f0f4f8', borderRadius: 6 }}>
            {filteredParties.map(p => {
              const sel = !!selParties.find(x => x.id === p.id);
              const idx = selParties.findIndex(x => x.id === p.id);
              return (
                <div key={p.id} onClick={() => toggleParty(p)}
                  style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '6px 10px', cursor: 'pointer',
                    background: sel ? '#dbeafe' : '#fff',
                    borderBottom: '1px solid #f0f4f8', userSelect: 'none' }}>
                  <div style={{ width: 20, height: 20, borderRadius: 4,
                    border: `2px solid ${sel ? '#1a3c5e' : '#cbd5e0'}`,
                    background: sel ? '#1a3c5e' : '#fff',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                    {sel && <span style={{ color: '#fff', fontSize: 12, fontWeight: 700 }}>✓</span>}
                  </div>
                  <div style={{ flex: 1 }}>
                    <span style={{ fontWeight: 700, fontSize: 12, color: '#1a3c5e' }}>[{p.party_code}]</span>
                    <span style={{ fontSize: 12, marginLeft: 5 }}>{p.party_name}</span>
                  </div>
                  {sel && (
                    <span style={{ background: '#1a3c5e', color: '#fff', fontSize: 10, fontWeight: 700, padding: '1px 6px', borderRadius: 99 }}>
                      P{idx + 1}
                    </span>
                  )}
                </div>
              );
            })}
          </div>

          {selParties.length > 0 && (
            <div style={{ marginTop: 8, fontSize: 11, color: '#1a3c5e', background: '#eff6ff', padding: '6px 10px', borderRadius: 6 }}>
              <b>{selParties.length} selected:</b> {selParties.map((p, i) => `P${i+1}:${p.party_code}`).join(' · ')}
            </div>
          )}
        </Card>

        {/* ── RIGHT: Sale selector + action ── */}
        <Card style={{ padding: 16, alignSelf: 'start' }}>
          <div style={{ fontWeight: 700, fontSize: 14, color: '#1a3c5e', marginBottom: 12 }}>Sale & Preview</div>
          <div style={{ display: 'flex', gap: 12, alignItems: 'flex-end', flexWrap: 'wrap' }}>
            <div>
              <label style={{ display: 'block', fontSize: 11, fontWeight: 700, color: '#555', marginBottom: 4, textTransform: 'uppercase', letterSpacing: 0.4 }}>
                Sale Number *
              </label>
              <select value={saleNo} onChange={e => setSaleNo(e.target.value)}
                style={{ padding: '8px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, minWidth: 200 }}>
                <option value="">Select sale…</option>
                {saleNos.map(s => (
                  <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>
                ))}
              </select>
            </div>
            <Button onClick={runPreview} disabled={loading || !selParties.length || !saleNo} variant="primary">
              {loading ? '⏳ Fetching…' : '🔍 Preview Lots'}
            </Button>
            {preview.length > 0 && (
              <Button onClick={save} disabled={saving || activeCount === 0} variant="success">
                {saving ? 'Saving…' : `💾 Save ${activeCount} Markings`}
              </Button>
            )}
          </div>

          {preview.length > 0 && (
            <div style={{ marginTop: 10, fontSize: 12, color: '#555' }}>
              <b>{preview.length}</b> lots ·{' '}
              <b style={{ color: '#1a7a4a' }}>{activeCount}</b> active ·{' '}
              <b style={{ color: '#c0392b' }}>{Object.values(skipRows).filter(Boolean).length}</b> skipped
            </div>
          )}

          <div style={{ marginTop: 12, padding: 10, background: '#f8fafc', borderRadius: 6, fontSize: 12, color: '#888' }}>
            <b>Filters applied per party from Party Master:</b> Grade samples, Rate range, Broker list, Bags from/to, Net Wt from/to, Skip blank LSP, Skip duplicate Broker+Garden+Grade.
          </div>
        </Card>
      </div>

      {/* ── MARKING TABLE ── */}
      {preview.length > 0 && (
        <Card style={{ padding: 0, overflow: 'hidden' }}>
          <div style={{ padding: '12px 16px', background: '#1a3c5e', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div style={{ fontWeight: 700, fontSize: 14 }}>Marking List — Sale #{saleNo}</div>
            <div style={{ fontSize: 12, opacity: 0.8 }}>{preview.length} lots · {partyOrder.length} parties</div>
          </div>

          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
              <thead>
                <tr style={{ background: '#234d78', color: '#fff' }}>
                  <th style={{ padding: '8px 8px', textAlign: 'center', fontWeight: 600, whiteSpace: 'nowrap', minWidth: 40 }}>Skip</th>
                  {partyOrder.map((p, i) => (
                    <th key={i} style={{ padding: '8px 8px', textAlign: 'center', fontWeight: 600, whiteSpace: 'nowrap', background: '#1a3c5e', minWidth: 55 }}>
                      P{i+1}<br/>
                      <span style={{ fontSize: 10, fontWeight: 400, opacity: 0.8 }}>{p.party_code}</span>
                    </th>
                  ))}
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap' }}>Bro</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap' }}>Lot</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap', minWidth: 130 }}>Garden</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap' }}>Grd</th>
                  <th style={{ padding: '8px 8px', textAlign: 'right', fontWeight: 600, whiteSpace: 'nowrap' }}>Rate ₹</th>
                  <th style={{ padding: '8px 8px', textAlign: 'right', fontWeight: 600, whiteSpace: 'nowrap' }}>Qty</th>
                  <th style={{ padding: '8px 8px', textAlign: 'right', fontWeight: 600, whiteSpace: 'nowrap' }}>NWt</th>
                  <th style={{ padding: '8px 8px', textAlign: 'left',  fontWeight: 600, whiteSpace: 'nowrap', minWidth: 130 }}>+ Add Party</th>
                </tr>
              </thead>
              <tbody>
                {(() => {
                  let lastBroker = null;
                  return preview.map((row, i) => {
                    const skip = !!skipRows[row.catalogue_id];
                    const brokerHeader = row.broker !== lastBroker;
                    lastBroker = row.broker;
                    const inputVal = addInputs[row.catalogue_id] || '';
                    const suggestions = getCodeSuggestions(inputVal);

                    return (
                      <React.Fragment key={row.catalogue_id}>
                        {brokerHeader && (
                          <tr>
                            <td colSpan={9 + partyOrder.length + 1}
                              style={{ background: '#e8f0fe', padding: '5px 10px', fontWeight: 700, fontSize: 12, color: '#1a3c5e', borderBottom: '1px solid #c7d2fe' }}>
                              Broker: {row.broker}
                            </td>
                          </tr>
                        )}
                        <tr style={{ borderBottom: '1px solid #f0f4f8', background: skip ? '#fff5f5' : (i % 2 === 0 ? '#fff' : '#fafbfc'), opacity: skip ? 0.4 : 1 }}>
                          {/* Skip */}
                          <td style={{ padding: '5px 8px', textAlign: 'center' }}>
                            <input type="checkbox" checked={skip}
                              onChange={() => setSkipRows(s => ({ ...s, [row.catalogue_id]: !s[row.catalogue_id] }))} />
                          </td>

                          {/* P1..Pn */}
                          {partyOrder.map((p, idx) => {
                            const allocated = row.party_cols && row.party_cols[p.key];
                            return (
                              <td key={idx} style={{ padding: '5px 8px', textAlign: 'center' }}>
                                {allocated
                                  ? <span style={{ background: '#1a3c5e', color: '#fff', padding: '2px 8px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>✓</span>
                                  : <span style={{ color: '#e2e8f0', fontSize: 11 }}>—</span>
                                }
                              </td>
                            );
                          })}

                          {/* Extra party badges */}
                          {extraParties[row.catalogue_id] && Object.values(extraParties[row.catalogue_id]).map((ep, ei) => (
                            <td key={`ex-${ei}`} style={{ padding: '5px 8px', textAlign: 'center' }}>
                              <span style={{ background: '#f59e0b', color: '#fff', padding: '2px 7px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>
                                {ep.party_code}
                              </span>
                            </td>
                          ))}

                          <td style={{ padding: '5px 8px', color: '#666', fontWeight: 600 }}>{row.broker}</td>
                          <td style={{ padding: '5px 8px', fontFamily: 'monospace', fontSize: 11, color: '#888' }}>{row.lot_no}</td>
                          <td style={{ padding: '5px 8px', fontWeight: 700, color: '#1a3c5e', maxWidth: 150, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {row.garden}
                          </td>
                          <td style={{ padding: '5px 8px' }}>
                            <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 7px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>
                              {row.grade}
                            </span>
                          </td>
                          {/* Rate — editable */}
                          <td style={{ padding: '5px 8px', textAlign: 'right' }}>
                            <input type="number" value={prices[row.catalogue_id] || ''} disabled={skip}
                              onChange={e => setPrices(p => ({ ...p, [row.catalogue_id]: e.target.value }))}
                              style={{ width: 65, padding: '3px 5px', border: '1.5px solid #cbd5e0', borderRadius: 5, fontSize: 12, fontFamily: 'monospace', textAlign: 'right' }} />
                          </td>
                          <td style={{ padding: '5px 8px', textAlign: 'right', fontWeight: 600 }}>{row.bags || '—'}</td>
                          <td style={{ padding: '5px 8px', textAlign: 'right' }}>{row.net_wt || '—'}</td>

                          {/* Add party input with dropdown */}
                          <td style={{ padding: '5px 8px' }}>
                            <div style={{ position: 'relative', display: 'inline-block' }}>
                              <div style={{ display: 'flex', gap: 4, alignItems: 'center' }}>
                                <input
                                  ref={el => { addInputRefs.current[row.catalogue_id] = el; }}
                                  value={inputVal}
                                  onChange={e => setAddInputs(prev => ({ ...prev, [row.catalogue_id]: e.target.value.toUpperCase() }))}
                                  onKeyDown={e => handleAddKeyDown(e, row.catalogue_id)}
                                  placeholder="Code"
                                  maxLength={5}
                                  title="Type party code and press Enter"
                                  style={{ width: 55, padding: '3px 6px', border: '1.5px solid #cbd5e0', borderRadius: 5, fontSize: 11, fontFamily: 'monospace', textTransform: 'uppercase' }}
                                />
                                <button onClick={() => addExtraParty(row.catalogue_id)}
                                  title="Add party (or press Enter)"
                                  style={{ padding: '3px 8px', background: '#1a3c5e', color: '#fff', border: 'none', borderRadius: 5, cursor: 'pointer', fontSize: 11, fontWeight: 700 }}>
                                  +
                                </button>
                              </div>
                              {/* Autocomplete dropdown */}
                              {suggestions.length > 0 && inputVal.length > 0 && (
                                <div style={{ position: 'absolute', top: '100%', left: 0, background: '#fff', border: '1px solid #e2e8f0', borderRadius: 6, zIndex: 999, boxShadow: '0 4px 12px rgba(0,0,0,0.1)', minWidth: 160 }}>
                                  {suggestions.map(s => (
                                    <div key={s.id}
                                      onMouseDown={e => {
                                        e.preventDefault();
                                        setAddInputs(prev => ({ ...prev, [row.catalogue_id]: s.party_code }));
                                        setTimeout(() => addExtraParty(row.catalogue_id), 50);
                                      }}
                                      style={{ padding: '6px 10px', cursor: 'pointer', fontSize: 12, borderBottom: '1px solid #f0f4f8' }}
                                      onMouseEnter={e => e.currentTarget.style.background = '#f0f8ff'}
                                      onMouseLeave={e => e.currentTarget.style.background = '#fff'}>
                                      <b>{s.party_code}</b> — {s.party_name}
                                    </div>
                                  ))}
                                </div>
                              )}
                            </div>
                          </td>
                        </tr>
                      </React.Fragment>
                    );
                  });
                })()}
              </tbody>
            </table>
          </div>
        </Card>
      )}
    </div>
  );
}
